from decimal import ROUND_DOWN, Decimal

from django.db import migrations, models


def repartir_puntos(apps, schema_editor):
    """Las evaluaciones que ya existían: 10 puntos en partes iguales (lo que
    sobra del redondeo, en la última) y la nota de cada intento sobre 10."""
    Material = apps.get_model("capacitacion", "Material")
    Pregunta = apps.get_model("capacitacion", "Pregunta")
    Intento = apps.get_model("capacitacion", "Intento")
    for material in Material.objects.all():
        preguntas = list(Pregunta.objects.filter(material=material).order_by("orden", "id"))
        if not preguntas:
            continue
        parte = (Decimal(10) / len(preguntas)).quantize(Decimal("0.01"), rounding=ROUND_DOWN)
        for i, pregunta in enumerate(preguntas):
            ultima = i == len(preguntas) - 1
            pregunta.puntos = Decimal(10) - parte * (len(preguntas) - 1) if ultima else parte
            pregunta.save(update_fields=["puntos"])
    for intento in Intento.objects.filter(nota__isnull=True):
        intento.nota = (Decimal(intento.puntaje) / 10).quantize(Decimal("0.01"))
        intento.save(update_fields=["nota"])


